import { defineCollection, z } from "astro:content";
import { glob } from "astro/loaders";
import { TOPIC_ROOTS } from "./data/topic-roots";

/**
 * Steps come from two folders. `src/content/topics` is generated by
 * `npm run import` from the material (ADR-002) and the importer owns all of it;
 * `src/authored/topics` holds the steps written for the site (ADR-019). Entry ids
 * keep the folder prefix so the two can never collide; the URL and the progress
 * key come from category + file name (`topicId`), not from the id.
 *
 * Schema failures break the build on purpose: a topic without a title or with
 * an unknown origin means the importer or the source drifted.
 */
const topics = defineCollection({
  loader: glob({ pattern: TOPIC_ROOTS.map((root) => `${root.dir}/**/*.md`), base: "./src" }),
  schema: z.object({
    title: z.string(),
    /** "15.3" for imported topics, empty for pages written for this site. */
    sectionNumber: z.string(),
    category: z.string(),
    order: z.number().int().positive(),
    cardCount: z.number().int().nonnegative(),
    sourceFile: z.string().optional(),
    origin: z.enum(["material", "new"]).default("material"),
    flags: z.array(z.enum(["degisken", "emin-degil"])).default([]),
    /** Sources are required for pages written outside the material. */
    sources: z.array(z.object({ label: z.string(), url: z.string().url() })).default([]),
  }),
});

const categories = defineCollection({
  loader: glob({ pattern: "*.md", base: "./src/content/categories" }),
  schema: z.object({
    category: z.string(),
    sourceFiles: z.array(z.string()).default([]),
  }),
});

// One JSON per category; the entry id is the category slug.
const quizzes = defineCollection({
  loader: glob({ pattern: "*.json", base: "./src/content/quizzes" }),
  schema: z.object({
    category: z.string(),
    source: z.string(),
    items: z.array(z.object({ n: z.number(), question: z.string(), answer: z.string() })),
  }),
});

/**
 * Hand-written lessons (ADR-015). They live outside src/content/ on purpose:
 * that folder is generated and `import:check` guards it. A lesson is matched to
 * an imported step by file path — `web-temelleri/istemci-sunucu-modeli.mdx`
 * replaces the term-card view of that step. `_index.mdx` is the category landing.
 */
const lessons = defineCollection({
  loader: glob({ pattern: "**/*.mdx", base: "./src/lessons" }),
  schema: z.object({
    /** One-sentence promise shown under the title and in link previews. */
    summary: z.string(),
    /** "Bu derste öğreneceklerin" — what the reader can do afterwards. */
    outcomes: z.array(z.string()).default([]),
    minutes: z.number().int().positive().optional(),
    /** Primary sources; a lesson without one does not build (CLAUDE.md rule 4). */
    sources: z.array(z.object({ label: z.string(), url: z.string().url() })).min(1),
    /** Facts that are not in the material — listed on the page and in the round report. */
    additions: z.array(z.string()).default([]),
    flags: z.array(z.enum(["degisken", "emin-degil"])).default([]),
    /** Ordinary words this lesson means as glossary terms ("card", "table"); see rehype-term-refs. */
    includeTerms: z.array(z.string()).default([]),
    /** Words whose shared definition is the wrong one here ("header" in page anatomy). */
    skipTerms: z.array(z.string()).default([]),
    /** 2 = written to lesson standard v2 (docs/icerik/ders-standardi.md); lint:lessons enforces it. */
    standard: z.union([z.literal(1), z.literal(2)]).default(1),
    /** Step ids that should be read first. */
    requires: z.array(z.string()).default([]),
  }),
});

/**
 * The Roller pages (ADR-017): one file per role id in src/data/role-ids.ts. The
 * route itself lives in src/data/roles.ts; this is the description of the job.
 * Everything here is outside the material, so sources are mandatory.
 */
const roles = defineCollection({
  loader: glob({ pattern: "*.mdx", base: "./src/roles" }),
  schema: z.object({
    /** Over what time span the role's decisions mostly play out. */
    horizon: z.string(),
    /** What the role is answerable for. */
    accountable: z.array(z.string()).min(1),
    /** Decisions the role shapes but does not own. */
    contributes: z.array(z.string()).default([]),
    /** Decisions that belong to someone else, said plainly. */
    notOwner: z.array(z.string()).default([]),
    /** What the role typically produces. */
    artifacts: z.array(z.string()).min(1),
    neighbours: z.array(z.object({ role: z.string(), difference: z.string() })).default([]),
    sources: z.array(z.object({ label: z.string(), url: z.string().url() })).min(1),
    /** When the facts on the page were last checked (certifications drift). */
    checked: z.string(),
  }),
});

/**
 * Quizzes written for the site (src/authored/quizzes/<kategori>.json). One for a
 * category the material has no quiz for, or — with `overrides: true` — a
 * rewrite that replaces the imported one (role-neutral, scenario questions).
 * Lesson standard v2 asks for at least eight questions.
 */
const authoredQuizzes = defineCollection({
  loader: glob({ pattern: "*.json", base: "./src/authored/quizzes" }),
  schema: z.object({
    category: z.string(),
    overrides: z.boolean().default(false),
    sources: z.array(z.object({ label: z.string(), url: z.string().url() })).min(1),
    items: z
      .array(
        z.object({
          question: z.string(),
          answer: z.string(),
          /** Shown only to these roles (and in Keşif); omitted = everyone. */
          roles: z.array(z.string()).optional(),
        }),
      )
      .min(8),
  }),
});

/**
 * Araçlar → şablonlar (plan §3.4): src/tools/sablonlar/<slug>/index.mdx is the
 * page — what the template is for, when, who owns it. A "belge" template keeps
 * its filled example and its blank copy beside it (ornek.md, bos.md); a
 * "tablo" template carries its columns and example rows in `table`, from which
 * the page, the Markdown and the CSV are all generated.
 */
const templates = defineCollection({
  loader: glob({
    pattern: "*/index.mdx",
    base: "./src/tools/sablonlar",
    generateId: ({ entry }) => entry.split("/")[0]!,
  }),
  schema: z.object({
    title: z.string(),
    summary: z.string(),
    kind: z.enum(["belge", "tablo"]),
    /** Role ids that usually own or use it. */
    roles: z.array(z.string()).min(1),
    /** Step ids (category/slug) that teach it. */
    lessons: z.array(z.string()).default([]),
    sources: z.array(z.object({ label: z.string(), url: z.string().url() })).min(1),
    table: z
      .object({
        columns: z.array(z.string()).min(2),
        example: z.array(z.array(z.string())).min(1),
        blankRows: z.number().int().positive().default(6),
      })
      .optional(),
  }),
});

const templateDocs = defineCollection({
  loader: glob({
    pattern: "*/{ornek,bos}.md",
    base: "./src/tools/sablonlar",
    generateId: ({ entry }) => entry.replace(/\.md$/, ""),
  }),
  schema: z.object({}),
});

export const collections = { topics, categories, quizzes, lessons, roles, authoredQuizzes, templates, templateDocs };
